def transform(grid):
    from collections import Counter

    counts = Counter()
    for row in grid:
        counts.update(row)

    bg_color = max(counts.keys(), key=lambda c: counts[c])
    colors = set(counts.keys()) - {bg_color}
    signal_color = list(colors)[0] if colors else bg_color

    h, w = len(grid), len(grid[0])

    # Identify output dimensions by counting row/col sections with signal
    row_sections = 0
    in_section = False
    for r in range(h):
        has_signal = any(grid[r][c] == signal_color for c in range(w))
        if has_signal and not in_section:
            row_sections += 1
            in_section = True
        elif not has_signal and in_section:
            in_section = False

    col_sections = 0
    in_section = False
    for c in range(w):
        has_signal = any(grid[r][c] == signal_color for r in range(h))
        if has_signal and not in_section:
            col_sections += 1
            in_section = True
        elif not has_signal and in_section:
            in_section = False

    output_h = max(1, row_sections)
    output_w = max(1, col_sections)

    output = [[bg_color for _ in range(output_w)] for _ in range(output_h)]

    # Map signal positions to output
    for r in range(h):
        for c in range(w):
            if grid[r][c] == signal_color:
                out_r = (r * output_h) // h if h > 0 else 0
                out_c = (c * output_w) // w if w > 0 else 0
                if 0 <= out_r < output_h and 0 <= out_c < output_w:
                    output[out_r][out_c] = signal_color

    return output
